"""
Structural data on the small-q counterexamples (q = 7, 11, 19, 23, 31):
  * the group H generated by all C(m,2) crossing involutions sigma_{pi,rho}, and whether M is H-invariant;
  * lambda_max of the matrix K_{uv} = chi([u,v][psi u, psi v])  (the canonical solution has lambda_max = q).
"""
import itertools
import numpy as np

EX = {7: [(1, 3), (2, 6), (4, 5)],
      11: [(1, 2), (3, 6), (4, 8), (5, 10), (7, 9)],
      19: [(1, 2), (3, 4), (5, 8), (6, 13), (7, 10), (9, 15), (11, 18), (12, 16), (14, 17)],
      23: [(1, 5), (2, 7), (3, 22), (4, 20), (6, 15), (8, 14), (9, 10), (11, 16), (12, 19), (13, 21), (17, 18)],
      31: [(1, 3), (2, 30), (4, 24), (5, 15), (6, 19), (7, 11), (8, 29), (9, 21), (10, 26), (12, 14),
           (13, 25), (16, 23), (17, 28), (18, 22), (20, 27)]}

for q, prs in EX.items():
    INF = q
    inv = lambda a: pow(a, q - 2, q)
    sq = {x * x % q for x in range(1, q)}
    chi = lambda a: 0 if a % q == 0 else (1 if a % q in sq else -1)
    pairs = [(0, INF)] + prs
    P = {}
    for a, b in pairs:
        P[a] = b
        P[b] = a

    def mob(M, z):
        a, b, c, d = M
        if z == INF:
            return INF if c == 0 else a * inv(c) % q
        num, den = (a * z + b) % q, (c * z + d) % q
        return INF if den == 0 else num * inv(den) % q

    def norm(M):
        a, b, c, d = [x % q for x in M]
        t = inv(next(x for x in (a, b, c, d) if x))
        return tuple(x * t % q for x in (a, b, c, d))

    def invol(p1, p2):  # the Moebius involution having p1 and p2 as orbits
        rows = []
        for (a, b) in (p1, p2):
            if a == INF:
                a, b = b, a
            rows.append((-1, 0, a) if b == INF else (-(a + b) % q, -1 % q, a * b % q))
        (x1, y1, z1), (x2, y2, z2) = rows
        A, B, C = (y1 * z2 - z1 * y2) % q, (z1 * x2 - x1 * z2) % q, (x1 * y2 - y1 * x2) % q
        return norm((A, B, C, -A))

    def compose(M, N):
        a, b, c, d = M
        e, f, g, h = N
        return norm((a * e + b * g, a * f + b * h, c * e + d * g, c * f + d * h))

    gens = {invol(p1, p2) for p1, p2 in itertools.combinations(pairs, 2)}
    H, frontier = set(gens), list(gens)
    while frontier and len(H) <= 20000:
        new = []
        for g in frontier:
            for s in gens:
                h = compose(g, s)
                if h not in H:
                    H.add(h)
                    new.append(h)
        frontier = new
    Mset = {frozenset(p) for p in pairs}
    Minv = all(frozenset((mob(g, a), mob(g, b))) in Mset for g in gens for (a, b) in pairs)
    pc = lambda x: (1, 0) if x == INF else (x, 1)
    det = lambda A, B: (A[0] * B[1] - A[1] * B[0]) % q
    N = q + 1
    K = np.zeros((N, N))
    for u in range(N):
        for v in range(N):
            if u != v:
                K[u, v] = chi(det(pc(u), pc(v))) * chi(det(pc(P[u]), pc(P[v])))
    lam = np.linalg.eigvalsh(K)
    print(f"q={q}: |H|={len(H)} (|PSL(2,q)|={q*(q*q-1)//2}), M invariant under H: {Minv}, "
          f"lambda_max(K)={lam[-1]:.3f} vs q={q}")
